content.content:
1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>Doc-audit | FirstRun</title>
7	<meta name="description" content="Which docs pages are stale, which shipped features have no docs, and what your docs team should ship next. Built from the git history.">
8	<meta name="color-scheme" content="light">
9	<link rel="icon" href="../assets/logo.svg" type="image/svg+xml">
10	<link rel="stylesheet" href="../assets/site-nav.css">
11	<link rel="preconnect" href="https://fonts.googleapis.com">
12	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
13	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500&display=swap">
14	<style>
15	:root{
16	--bg:oklch(98.2% .004 255);--panel:oklch(99.7% .0015 255);--sunk:oklch(97.1% .005 255);--hover:oklch(96.2% .007 255);
17	--line:oklch(91.6% .007 255);--line2:oklch(94.6% .005 255);
18	--ink:oklch(22% .012 255);--ink2:oklch(36% .012 255);--mut:oklch(50% .013 255);--faint:oklch(68% .01 255);
19	--acc:oklch(55% .19 256);--acc-bg:oklch(95.6% .026 256);
20	--vio:oklch(52% .2 295);--vio-bg:oklch(95.8% .03 295);
21	--ok:oklch(52% .14 150);--ok-bg:oklch(96.4% .032 150);
22	--bad:oklch(53% .19 27);--bad-bg:oklch(96.6% .02 27);
23	--warn:oklch(52% .12 66);--warn-bg:oklch(96.2% .045 85);
24	--sh:0 1px 2px oklch(30% .02 255/.06);--sh2:0 1px 3px oklch(30% .02 255/.08),0 16px 40px -12px oklch(30% .04 255/.26);
25	--ease:cubic-bezier(.22,1,.36,1);--mono:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
26	*{box-sizing:border-box;margin:0}
27	html{background:var(--bg);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%}
28	body{line-height:1.45;font-size:15px;-webkit-font-smoothing:antialiased;background:var(--bg);min-height:100vh}
29	a{color:var(--acc);text-underline-offset:3px}
30	button{font:inherit;color:inherit}
31	code,.mono{font-family:var(--mono)}
32	:focus-visible{outline:3px solid var(--acc);outline-offset:2px;border-radius:8px}
33	[hidden]{display:none!important}
34	.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
35	svg.i{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
36	main{max-width:1240px;margin:0 auto;padding:24px 20px 72px}
37	h1{font-size:34px;line-height:1.1;letter-spacing:-.035em;font-weight:700}
38	h2{font-size:19px;letter-spacing:-.02em;font-weight:650}
39	.lede{font-size:16px;color:var(--mut);margin-top:6px;max-width:58ch}
40	.sec{margin-top:36px}
41	.sec-h{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}
42	.sec-h p{color:var(--mut);font-size:13.5px}
43	.btn{display:inline-flex;align-items:center;gap:7px;height:36px;padding:0 14px;border-radius:10px;border:1px solid var(--line);background:var(--panel);color:var(--ink);font-weight:600;font-size:13.5px;text-decoration:none;cursor:pointer;white-space:nowrap;box-shadow:var(--sh)}
44	.btn:hover{background:var(--hover)}
45	.btn.pri{background:var(--vio);border-color:transparent;color:oklch(99% .005 295)}
46	.btn.pri:hover{background:oklch(47% .2 295)}
47	.tile{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:8px;flex:none;color:oklch(99% .005 255)}
48	.tile svg.i{width:16px;height:16px}
49	.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;box-shadow:var(--sh)}
50	.back{display:inline-flex;align-items:center;gap:6px;font-size:13.5px;color:var(--mut);text-decoration:none}
51	.back:hover{color:var(--ink)}
52	.av{width:40px;height:40px;border-radius:10px;background:var(--sunk);border:1px solid var(--line);flex:none;object-fit:cover}
53	
54	/* start view */
55	.lh-top{display:flex;gap:16px;align-items:flex-start}
56	.lh-top .sn-tile{width:52px;height:52px;border-radius:14px;margin-top:4px}.lh-top .sn-tile svg{width:28px;height:28px}
57	.ask{display:flex;gap:8px;align-items:center;margin-top:22px;max-width:640px;padding:6px 6px 6px 16px}
58	.ask svg.i{color:var(--mut)}
59	.ask input{flex:1;min-width:0;font:inherit;font-size:15.5px;border:0;background:none;color:var(--ink);padding:8px 0;outline:0}
60	.mode{display:inline-flex;gap:4px;margin-top:22px;padding:4px;border-radius:12px;background:var(--sunk);border:1px solid var(--line)}
61	.mode button{display:inline-flex;align-items:center;gap:7px;height:34px;padding:0 14px;border:0;border-radius:9px;background:none;font-weight:600;font-size:13.5px;color:var(--mut);cursor:pointer}
62	.mode button svg.i{width:15px;height:15px}
63	.mode button[aria-pressed=true]{background:var(--panel);color:var(--ink);box-shadow:var(--sh)}
64	.ask.top{margin-top:10px}
65	.hint{font-size:13px;color:var(--mut);margin-top:8px;max-width:640px}
66	.steps{list-style:none;padding:0;margin-top:12px;max-width:760px;display:grid;gap:8px}
67	.steps li{display:grid;grid-template-columns:28px minmax(0,1fr);gap:4px 12px;padding:12px 14px}
68	.steps .n{grid-row:1/span 3;width:26px;height:26px;border-radius:99px;display:grid;place-items:center;font-size:13px;font-weight:700;background:var(--vio-bg);color:var(--vio)}
69	.steps b{font-size:14.5px}
70	.steps span{font-size:13px;color:var(--mut)}
71	.steps .opt{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--vio);margin-left:8px}
72	.steps .dw-acts{margin-top:6px}
73	.code{display:flex;align-items:center;gap:8px;margin-top:4px;background:var(--sunk);border:1px solid var(--line);border-radius:9px;padding:6px 6px 6px 12px;font:12.5px var(--mono);overflow-x:auto}
74	.code code{flex:1;white-space:pre}
75	.code .btn{height:30px;padding:0 10px;flex:none}
76	.cmd{display:flex;gap:10px;align-items:flex-start;justify-content:space-between;margin-top:10px;max-width:640px;padding:12px 12px 12px 16px;font-size:13px}
77	.cmd code{white-space:pre;overflow-x:auto}
78	.flow{padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin-top:14px;overflow:hidden}
79	.flow li{list-style:none;display:flex;gap:12px;align-items:flex-start;padding:16px 18px;position:relative}
80	.flow li+li{border-left:1px solid var(--line2)}
81	.flow b{display:block;font-size:14.5px}
82	.flow span{font-size:13px;color:var(--mut)}
83	.flow .tile{background:var(--vio-bg);color:var(--vio)}
84	.alist{list-style:none;padding:0;overflow:hidden}
85	.alist li+li{border-top:1px solid var(--line2)}
86	.alist a{display:grid;grid-template-columns:40px minmax(0,1fr) 220px auto;gap:4px 16px;align-items:center;padding:14px 18px;color:inherit;text-decoration:none}
87	.alist li:hover{background:var(--hover)}
88	.alist .rcpw{padding:0 18px 14px 74px;margin-top:-4px}
89	.alist a.rcp,.rcp{display:inline-flex;grid-template-columns:none;align-items:center;gap:7px;min-height:30px;padding:3px 13px 3px 10px;border-radius:99px;border:1px solid var(--line);background:var(--panel);color:var(--ink);font-size:13px;font-weight:600;text-decoration:none;box-shadow:var(--sh);transition:border-color .15s,color .15s,background .15s}
90	.rcp svg.i{width:15px;height:15px;color:var(--vio)}
91	.rcp .lbl{text-decoration:underline;text-decoration-color:oklch(80% .08 295);text-underline-offset:3px}
92	.rcp .sep{color:var(--faint);font-weight:400}
93	.rcp .amt{font-family:var(--mono);font-variant-numeric:tabular-nums}
94	.rcp .nc{font-weight:400;color:var(--mut)}
95	.alist a.rcp:hover,.rcp:hover{border-color:var(--vio);color:var(--vio);background:var(--vio-bg)}
96	.rcp:hover .lbl{text-decoration-color:currentColor}
97	.rh .acts .rcp{height:36px;min-height:36px;border-radius:10px;padding:0 14px 0 12px}
98	.alist .nm{font-weight:650;font-size:15.5px;letter-spacing:-.01em}
99	.alist .nm small{display:block;font-weight:400;font-size:12.5px;color:var(--mut)}
100	.alist .go{color:var(--vio);font-weight:600;font-size:13.5px;display:inline-flex;gap:4px;align-items:center}
101	.minis{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
102	
103	/* chips */
104	.chip{display:inline-flex;align-items:center;gap:5px;height:24px;padding:0 9px;border-radius:99px;font-size:12.5px;font-weight:600;background:var(--sunk);color:var(--ink2);border:1px solid transparent;white-space:nowrap}
105	.chip svg.i{width:13px;height:13px}
106	.c-stale{background:var(--bad-bg);color:var(--bad)}.c-unchecked{background:var(--warn-bg);color:var(--warn)}
107	.c-quiet{background:var(--sunk);color:var(--mut)}.c-aging{background:var(--warn-bg);color:var(--warn)}.c-fresh{background:var(--ok-bg);color:var(--ok)}
108	.c-gap{background:var(--vio-bg);color:var(--vio)}
109	button.chip{cursor:pointer}
110	button.chip[aria-pressed=true]{border-color:currentColor}
111	
112	/* report: head and health */
113	.rh{display:flex;gap:14px;align-items:center;margin-top:10px;flex-wrap:wrap}
114	.rh h1{font-size:28px}
115	.rh .meta{color:var(--mut);font-size:13.5px;margin-top:2px}
116	.rh .acts{margin-left:auto;display:flex;gap:8px}
117	.health{margin-top:18px;padding:14px 16px;display:grid;gap:10px}
118	.bar{display:flex;height:10px;border-radius:99px;overflow:hidden;background:var(--line2);gap:2px}
119	.bar i{display:block;height:100%}
120	.b-stale{background:var(--bad)}.b-unchecked{background:oklch(72% .15 75)}.b-quiet{background:var(--faint)}.b-aging{background:oklch(82% .12 85)}.b-fresh{background:var(--ok)}
121	.hrow{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
122	.hrow .lbl{font-size:13px;color:var(--mut);margin-right:4px}
123	.hrow .sp{flex:1}
124	
125	/* kanban */
126	.board{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;align-items:start}
127	.col{background:var(--sunk);border:1px solid var(--line);border-radius:14px;display:flex;flex-direction:column;min-width:0;max-height:640px}
128	.col-h{display:flex;align-items:center;gap:10px;padding:12px 12px 10px}
129	.col-h b{font-size:14.5px;letter-spacing:-.01em}
130	.col-h .n{margin-left:auto;font-size:12.5px;font-weight:600;color:var(--mut);background:var(--panel);border:1px solid var(--line);border-radius:99px;padding:1px 8px}
131	.col-s{font-size:12.5px;color:var(--mut);padding:0 12px 10px;line-height:1.4}
132	.col-b{display:flex;flex-direction:column;gap:8px;padding:0 8px 8px;overflow-y:auto}
133	.k-document .tile{background:var(--bad)}.k-refresh .tile{background:oklch(64% .14 70)}.k-feature .tile{background:var(--acc)}.k-content .tile{background:var(--vio)}
134	.k-automate .tile{background:var(--ok)}.k-quickstart .tile{background:var(--ink)}
135	.kc{display:flex;flex-direction:column;gap:6px;text-align:left;width:100%;background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:11px 12px;cursor:pointer;box-shadow:var(--sh);transition:border-color .15s,transform .2s var(--ease)}
136	.kc:hover{border-color:oklch(82% .02 255);transform:translateY(-1px)}
137	.kc[aria-expanded=true]{border-color:var(--vio);box-shadow:0 0 0 3px var(--vio-bg)}
138	.kc .t{font-weight:600;font-size:13.5px;line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
139	.kc .p{font:12px var(--mono);color:var(--mut);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
140	.kc .m{display:flex;gap:10px;align-items:center;font-size:12px;color:var(--mut)}
141	.kc .m span{display:inline-flex;align-items:center;gap:4px}
142	.kc .m svg.i{width:13px;height:13px}
143	.kc .hot{color:var(--bad);font-weight:600}
144	.allgood{display:flex;gap:12px;align-items:center;padding:16px 18px;flex-wrap:wrap}.allgood p{color:var(--ink2);font-size:14.5px}
145	.col-empty{font-size:13px;color:var(--mut);padding:10px 12px 14px}
146	
147	/* ready for you */
148	.ready{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
149	.rd{display:flex;gap:12px;align-items:flex-start;text-align:left;padding:14px 16px;cursor:pointer;width:100%}
150	.rd:hover{background:var(--hover)}
151	.rd b{display:block;font-size:14.5px}
152	.rd span{font-size:13px;color:var(--mut)}
153	.rd .go{margin-left:auto;color:var(--mut);align-self:center}
154	.rd .tile,.dw-h .tile{color:oklch(99% .005 255)}
155	
156	/* pages table */
157	.tw{overflow:hidden}
158	table{width:100%;border-collapse:collapse;font-size:13.5px}
159	th,td{text-align:left;padding:9px 14px;border-bottom:1px solid var(--line2);vertical-align:middle}
160	tr:last-child td{border-bottom:0}
161	th{font-size:11.5px;color:var(--mut);font-weight:600;text-transform:uppercase;letter-spacing:.05em;background:var(--sunk)}
162	td.path{overflow-wrap:anywhere}
163	td.path a{color:var(--ink);text-decoration:none;font-family:var(--mono);font-size:12.5px}
164	td.path a:hover{color:var(--acc);text-decoration:underline}
165	td.path small{display:block;color:var(--mut);font-size:12px}
166	.age{display:flex;align-items:center;gap:8px;white-space:nowrap;color:var(--ink2)}
167	.age i{display:block;height:5px;border-radius:99px;background:var(--faint);min-width:2px}
168	.jv{display:block;font-size:11px;color:var(--mut);margin-top:2px}
169	.more{margin-top:10px}
170	
171	/* drawer */
172	.scrim{position:fixed;inset:0;background:oklch(22% .02 255/.22);opacity:0;visibility:hidden;transition:opacity .25s var(--ease),visibility 0s .25s;z-index:80}
173	.scrim.on{opacity:1;visibility:visible;transition:opacity .25s var(--ease)}
174	.drawer{position:fixed;top:0;right:0;bottom:0;width:min(520px,100vw);background:var(--panel);border-left:1px solid var(--line);box-shadow:var(--sh2);z-index:81;transform:translateX(102%);transition:transform .32s var(--ease);display:flex;flex-direction:column;visibility:hidden}
175	.drawer.on{transform:none;visibility:visible}
176	.dw-h{display:flex;align-items:center;gap:10px;padding:16px 18px;border-bottom:1px solid var(--line2)}
177	.dw-h .kind{font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--mut)}
178	.dw-h .x{margin-left:auto;width:34px;height:34px;border-radius:9px;border:0;background:none;cursor:pointer;display:grid;place-items:center;color:var(--mut)}
179	.dw-h .x:hover{background:var(--hover);color:var(--ink)}
180	.dw-b{padding:18px;overflow-y:auto;display:flex;flex-direction:column;gap:18px}
181	.dw-b h3{font-size:20px;letter-spacing:-.02em;line-height:1.25;overflow-wrap:anywhere}
182	.dw-b .why{color:var(--ink2);font-size:14.5px}
183	.todo{background:var(--sunk);border:1px solid var(--line);border-radius:12px;padding:12px 14px;display:flex;gap:10px;align-items:flex-start}
184	.todo p{flex:1;font-size:14px;overflow-wrap:anywhere}
185	.todo.mono p{font-family:var(--mono);font-size:13px}
186	.lab{font-size:11.5px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--mut);margin-bottom:6px}
187	.evl{list-style:none;padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden}
188	.evl li+li{border-top:1px solid var(--line2)}
189	.evl a,.evl span.r{display:grid;grid-template-columns:18px 1fr;gap:2px 10px;padding:10px 12px;color:inherit;text-decoration:none}
190	.evl a:hover{background:var(--hover)}
191	.evl svg.i{grid-row:1/span 2;margin-top:2px;color:var(--mut)}
192	.evl b{font-weight:500;font-size:13.5px;overflow-wrap:anywhere}
193	.evl small{font-size:12px;color:var(--mut);font-family:var(--mono)}
194	.dw-acts{display:flex;flex-wrap:wrap;gap:8px}
195	pre.draft{white-space:pre-wrap;font:13px/1.55 var(--mono);background:var(--sunk);border:1px solid var(--line);border-radius:12px;padding:14px;max-height:52vh;overflow:auto}
196	.hl{padding:10px 0;border-top:1px solid var(--line2);font-size:14px}.hl:first-child{border-top:0}
197	.hl b{display:block}
198	.hl span{color:var(--mut);font-size:13px}
199	.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,16px);opacity:0;background:var(--ink);color:var(--panel);padding:9px 16px;border-radius:99px;font-size:13.5px;font-weight:500;z-index:90;transition:opacity .2s,transform .25s var(--ease);pointer-events:none}
200	.toast.on{opacity:1;transform:translate(-50%,0)}
201	footer{max-width:1240px;margin:0 auto;padding:0 20px 40px;color:var(--mut);font-size:13.5px}
202	
203	@media(max-width:1000px){.board{grid-template-columns:repeat(4,minmax(260px,82%));overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:8px;margin:0 -20px;padding-left:20px;padding-right:20px;scroll-padding-left:20px}.col{scroll-snap-align:start;max-height:560px}.ready{grid-template-columns:1fr}}
204	@media(max-width:760px){.flow{grid-template-columns:1fr}.flow li+li{border-left:0;border-top:1px solid var(--line2)}.alist a{grid-template-columns:40px minmax(0,1fr)}.alist .barw,.alist .go{grid-column:2}.lh-top .sn-tile{display:none}.hide-sm{display:none}.rh .acts{margin-left:0}h1{font-size:30px}}
205	@media(max-width:760px){thead{display:none}table,tbody,tr,td{display:block}tr{display:grid;grid-template-columns:auto 1fr;gap:6px 10px;padding:10px 14px;border-bottom:1px solid var(--line2)}td{padding:0;border:0}td.path{grid-column:1/-1}td.hide-sm{display:none}}
206	@media(prefers-reduced-motion:reduce){*{transition:none!important}}
207	</style>
208	</head>
